WITH gated AS (SELECT model FROM llm_gateway.usage_log WHERE {{ time_filter('timestamp') }} AND model != '' GROUP BY model HAVING count() >= 100) SELECT round(countIf(aborted = 1) * 100.0 / nullIf(countIf(is_stream = 1), 0), 2) AS "Cancels %", round(countIf(aborted = 2) * 100.0 / nullIf(countIf(is_stream = 1), 0), 2) AS "Provider Aborts %" FROM llm_gateway.usage_log WHERE {{ time_filter('timestamp') }} AND is_stream = 1 AND coalesce(nullIf(key_id,''), nullIf(api_key_id,''), 'unknown') IN ({{ gf_str_multi('api_key') }}) AND model IN ({{ gf_str_multi('model') }}) AND model IN (SELECT model FROM gated)